<?php
namespace App\Http\Controllers;
use App\Models\CareerRecord;
use App\Models\CareerSkill;
use App\Models\CareerLearningSession;
use App\Services\CareerService;
use App\Services\WorkspaceContext;
use App\Services\Identity;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Gate;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class CareerController {
 public function __construct(private WorkspaceContext $context,private CareerService $service){}
 private function workspace(Request $r){$w=$this->context->current($r);abort_unless($w->type==='personal'&&(int)$w->owner_id===(int)$r->user()->id,403);return $w;}
 private function allowed(Request $r,CareerRecord $record){$w=$this->workspace($r);abort_unless((int)$record->workspace_id===(int)$w->id,404);Gate::authorize('view',$record);return $w;}
 private function today(Request $r): string{return now()->setTimezone($r->user()->timezone?:'UTC')->toDateString();}
 public function index(Request $r){$w=$this->workspace($r);$d=$r->validate(['kind'=>['nullable',Rule::in(array_keys(CareerService::TYPES))],'q'=>'nullable|string|max:100','status'=>'nullable|string|max:24']);$q=CareerRecord::where('workspace_id',$w->id);foreach(['kind','status'] as $key)if(!empty($d[$key]))$q->where($key,$d[$key]);if(!empty($d['q']))$q->where(fn($q)=>$q->where('title','like','%'.$d['q'].'%')->orWhere('description','like','%'.$d['q'].'%'));$records=$q->latest('updated_at')->paginate(20)->withQueryString();$types=CareerService::TYPES;$stats=$this->service->stats($w,$this->today($r));return view('career.index',compact('records','types','stats','d'));}
 private function data(Request $r,?CareerRecord $record=null): array{
  $base=$r->validate(['kind'=>['required',Rule::in(array_keys(CareerService::TYPES))],'title'=>'required|string|max:200','description'=>'nullable|string|max:10000','target_date'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31','version'=>$record?'required|integer|min:1':'nullable|integer']);
  $type=CareerService::TYPES[$base['kind']];$keys=array_keys($type['fields']);$rules=['status'=>['required',Rule::in($type['states'])],'details'=>['nullable','array:'.implode(',',$keys)]];
  foreach($type['fields'] as $key=>$format)$rules['details.'.$key]=match($format){'long'=>'nullable|string|max:20000','url'=>'nullable|string|max:2048|url:http,https','email'=>'nullable|email:rfc|max:254','date'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31','percent'=>'nullable|integer|min:0|max:100','band'=>['nullable','numeric','min:0','max:9',function($attribute,$value,$fail){if(fmod((float)$value*2,1.0)!==0.0)$fail('Use half-band increments.');}],'section'=>['nullable',Rule::in(['listening','reading','writing','speaking','overall'])],default=>'nullable|string|max:300'};
  $extra=$r->validate($rules);$details=$extra['details']??[];
  if($base['kind']==='ielts'&&$extra['status']==='completed'&&(!isset($details['score'])||empty($details['section'])||empty($details['practice_date'])))throw ValidationException::withMessages(['details.score'=>'Completed practice requires section, score and date.']);
  if($base['kind']==='ielts'&&!empty($details['practice_date'])&&$details['practice_date']>$this->today($r))throw ValidationException::withMessages(['details.practice_date'=>'Practice date cannot be in the future.']);
  if($base['kind']==='certification'&&!empty($details['earned_date'])&&!empty($details['expiry_date'])&&$details['expiry_date']<$details['earned_date'])throw ValidationException::withMessages(['details.expiry_date'=>'Expiry cannot precede earned date.']);
  $base['description']=$base['description']??null;$base['target_date']=$base['target_date']??null;
  return $base+['status'=>$extra['status'],'details'=>$details];
 }
 public function create(Request $r){$this->workspace($r);$d=$r->validate(['kind'=>['nullable',Rule::in(array_keys(CareerService::TYPES))]]);$kind=$d['kind']??'roadmap';$type=CareerService::TYPES[$kind];$record=new CareerRecord(['kind'=>$kind,'status'=>$type['states'][0],'details'=>[]]);return view('career.form',compact('record','type'));}
 public function store(Request $r){$w=$this->workspace($r);$record=$this->service->save($w,$r->user(),$this->data($r));return redirect()->route('career.show',$record);}
 public function show(Request $r,CareerRecord $record){$this->allowed($r,$record);$type=CareerService::TYPES[$record->kind];$revisions=$record->revisions()->latest('version')->paginate(10);return view('career.show',compact('record','type','revisions'));}
 public function edit(Request $r,CareerRecord $record){$this->allowed($r,$record);$type=CareerService::TYPES[$record->kind];return view('career.form',compact('record','type'));}
 public function update(Request $r,CareerRecord $record){$w=$this->allowed($r,$record);Gate::authorize('update',$record);$this->service->save($w,$r->user(),$this->data($r,$record),$record);return redirect()->route('career.show',$record);}
 public function destroy(Request $r,CareerRecord $record){$w=$this->allowed($r,$record);Gate::authorize('delete',$record);DB::transaction(function()use($w,$r,$record){$this->service->lock($w,$r->user());CareerRecord::where('workspace_id',$w->id)->findOrFail($record->id)->delete();Identity::audit('career_record_deleted',$r->user(),$w);});return redirect()->route('career.index');}
 public function skills(Request $r){$w=$this->workspace($r);$skills=CareerSkill::where('workspace_id',$w->id)->orderByRaw('target_level - current_level DESC')->orderBy('name')->paginate(20);return view('career.skills',compact('skills'));}
 private function skillData(Request $r): array{return $r->validate(['name'=>'required|string|max:120','category'=>'required|string|max:80','current_level'=>'required|integer|min:0|max:5','target_level'=>'required|integer|min:1|max:5','evidence'=>'nullable|string|max:10000']);}
 public function saveSkill(Request $r,?CareerSkill $skill=null){$w=$this->workspace($r);if($skill)abort_unless((int)$skill->workspace_id===(int)$w->id,404);$d=$this->skillData($r);DB::transaction(function()use($w,$r,$skill,$d){$this->service->lock($w,$r->user());$s=$skill?CareerSkill::where('workspace_id',$w->id)->findOrFail($skill->id):new CareerSkill();$q=CareerSkill::where('workspace_id',$w->id)->where('name',$d['name']);if($s->exists)$q->whereKeyNot($s->id);if($q->exists())throw ValidationException::withMessages(['name'=>'Skill already exists.']);$s->workspace_id=$w->id;$s->fill($d);$s->save();Identity::audit('career_skill_saved',$r->user(),$w);});return redirect()->route('career.skills');}
 public function deleteSkill(Request $r,CareerSkill $skill){$w=$this->workspace($r);abort_unless((int)$skill->workspace_id===(int)$w->id,404);DB::transaction(function()use($w,$r,$skill){$this->service->lock($w,$r->user());CareerSkill::where('workspace_id',$w->id)->findOrFail($skill->id)->delete();Identity::audit('career_skill_deleted',$r->user(),$w);});return back();}
 public function learning(Request $r){$w=$this->workspace($r);$sessions=CareerLearningSession::where('workspace_id',$w->id)->latest('local_date')->latest('id')->paginate(30);$choices=CareerRecord::where('workspace_id',$w->id)->whereIn('kind',['course','lab','ielts','certification','roadmap'])->orderBy('title')->limit(200)->get(['id','title']);$today=$this->today($r);$stats=$this->service->stats($w,$today);return view('career.learning',compact('sessions','choices','today','stats'));}
 public function saveLearning(Request $r){$w=$this->workspace($r);$d=$r->validate(['topic'=>'required|string|max:200','local_date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:'.$this->today($r),'minutes'=>'required|integer|min:1|max:1440','reflection'=>'nullable|string|max:10000','career_record_id'=>'nullable|integer|min:1']);DB::transaction(function()use($w,$r,$d){$this->service->lock($w,$r->user());if(!empty($d['career_record_id'])&&!CareerRecord::where('workspace_id',$w->id)->whereIn('kind',['course','lab','ielts','certification','roadmap'])->whereKey($d['career_record_id'])->exists())throw ValidationException::withMessages(['career_record_id'=>'Choose your own learning record.']);$total=CareerLearningSession::where('workspace_id',$w->id)->where('local_date',$d['local_date'])->sum('minutes');if($total+$d['minutes']>1440)throw ValidationException::withMessages(['minutes'=>'Daily learning cannot exceed 24 hours.']);$s=new CareerLearningSession($d);$s->workspace_id=$w->id;$s->save();Identity::audit('career_learning_logged',$r->user(),$w);});return back();}
 public function deleteLearning(Request $r,CareerLearningSession $session){$w=$this->workspace($r);abort_unless((int)$session->workspace_id===(int)$w->id,404);DB::transaction(function()use($w,$r,$session){$this->service->lock($w,$r->user());CareerLearningSession::where('workspace_id',$w->id)->findOrFail($session->id)->delete();Identity::audit('career_learning_deleted',$r->user(),$w);});return back();}
}
